AND io.create_time >= #{startDate}
AND io.create_time <= #{endDate}
GROUP BY atd.awaiting_details_code ), -- 步骤2：查询当前年范围内已签约的销售合同对应的待发明细（用于统计需发货量） -- 对于在当前年范围内已经签约过的销售合同订单（state IN ('MUTUAL_SIGN', 'UNILATERAL_SIGN', 'SEALED')）内的产品， -- 即使没有发货记录，也需要添加到统计需发货产品数量 signedContracts AS ( SELECT sc.primary_key AS contract_code FROM ${sellContractTable} sc WHERE sc.enterprise_code = #{enterpriseCode} AND sc.delete_flag = 'f' AND sc.state IN ('MUTUAL_SIGN', 'UNILATERAL_SIGN', 'SEALED') AND sc.contract_time IS NOT NULL
AND sc.contract_time >= #{startDate}
AND sc.contract_time <= #{endDate}
) -- 步骤3：统计当前年时间段内总累计发货量和总需发货�? -- 已发货数量：统计有发货记录的产品 -- 需发货数量：统计所有在当前年范围内已签约的销售合同订单内的产品，不管是否有发货记�? SELECT NULL AS productCode, NULL AS productName, COALESCE(SUM(sh.shipped_total), 0) AS shippedTotal, SUM(COALESCE(ad.product_quantity, 0)) AS quantityTotal FROM ${awaitingDetailsTable} ad INNER JOIN signedContracts sc ON sc.contract_code = ad.contract_code LEFT JOIN shipped sh ON sh.awaiting_details_code = ad.primary_key WHERE ad.enterprise_code = #{enterpriseCode} AND ad.delete_flag = 'f'
